    fun getQuartersForJuz(juz: Int): List<QuranQuarter> {
        return QUARTERS.filter { it.juzNumber == juz }
    }

    fun getQuarterById(id: Int): QuranQuarter? {
        return QUARTERS.firstOrNull { it.id == id }
    }

    fun getQuarterByPage(page: Int): QuranQuarter? {
        return QUARTERS.lastOrNull { it.startPage <= page } ?: QUARTERS.firstOrNull()
    }
}
